graphql.query:
query GetCategoryTree {
  categoryTree {
    id
    name
    slug
    parentId
    sortOrder
    productCount
    childCount
    children {
      id
      name
      slug
      parentId
      sortOrder
      productCount
      childCount
    }
  }
}

query GetProducts($filter: ProductFilterInput, $pagination: PaginationInput) {
  products(filter: $filter, pagination: $pagination) {
    data {
      id
      name
      sku
      description
      price
      stock
      status
      categoryId
      category {
        id
        name
        slug
      }
    }
    meta {
      page
      limit
      total
      totalPages
    }
  }
}

query GetProduct($id: ID!) {
  product(id: $id) {
    id
    name
    sku
    description
    price
    stock
    status
    categoryId
    category {
      id
      name
      slug
      sortOrder
      productCount
    }
  }
}

query GetRecommendations($productId: ID!, $limit: Int) {
  recommendations(productId: $productId, limit: $limit) {
    id
    name
    sku
    description
    price
    stock
    status
    categoryId
    category {
      id
      name
      slug
    }
  }
}

query GetProductNotFound($id: ID!) {
  product(id: $id) {
    id
    name
  }
}

query GetMyOrders {
  myOrders {
    id
    status
    totalAmount
    createdAt
    items {
      id
      productId
      quantity
      price
      subtotal
      product {
        id
        name
        sku
        price
      }
    }
  }
}
